import java.util.*;

class Solution {
    public long taskSchedulerII(int[] tasks, int space) {
        Map<Integer, Long> last = new HashMap<>();
        long day = 0;
        for (int t : tasks) {
            day++;
            while (last.containsKey(t) && day - last.get(t) <= space) day++; // break day
            last.put(t, day);
        }
        return day;
    }
}

