def canRearrangeKApart(s, k):
    if k <= 1:
        return True
    count = [0] * 26
    for ch in s:
        count[ord(ch) - 97] += 1
    last = [-k] * 26
    for i in range(len(s)):
        best = -1
        for c in range(26):
            if count[c] and i - last[c] >= k and (best < 0 or count[c] > count[best]):
                best = c
        if best < 0:
            return False
        count[best] -= 1
        last[best] = i
    return True

