function leastInterval(tasks, n) {
    const count = {};
    for (const t of tasks) count[t] = (count[t] || 0) + 1;
    let remaining = Object.values(count).sort((a, b) => b - a);
    let time = 0;
    while (remaining.length) {
        // each cycle runs up to n + 1 tasks, most frequent first
        const cycle = remaining.slice(0, n + 1);
        const rest = remaining.slice(n + 1);
        for (const cnt of cycle) {
            if (cnt - 1 > 0) rest.push(cnt - 1);
        }
        remaining = rest.sort((a, b) => b - a);
        // a full cycle (idles included) unless this was the last one
        time += remaining.length ? n + 1 : cycle.length;
    }
    return time;
}

