class Solution {
    public int leastInterval(char[] tasks, int n) {
        int[] count = new int[26];
        for (char t : tasks) count[t - 'A']++;
        List<Integer> freqs = new ArrayList<>();
        for (int c : count) if (c > 0) freqs.add(c);
        int time = 0;
        while (!freqs.isEmpty()) {
            // Each cycle of n+1 slots runs the n+1 most frequent remaining tasks
            freqs.sort(Collections.reverseOrder());
            int take = Math.min(n + 1, freqs.size());
            List<Integer> next = new ArrayList<>();
            for (int i = 0; i < freqs.size(); i++) {
                int f = i < take ? freqs.get(i) - 1 : freqs.get(i);
                if (f > 0) next.add(f);
            }
            // A full cycle (with idles) unless this was the last one
            time += next.isEmpty() ? take : n + 1;
            freqs = next;
        }
        return time;
    }
}

