import "sort"

func leastInterval(tasks []byte, n int) int {
    count := make([]int, 26)
    for _, t := range tasks {
        count[t-'A']++
    }
    freqs := []int{}
    for _, c := range count {
        if c > 0 {
            freqs = append(freqs, c)
        }
    }
    time := 0
    for len(freqs) > 0 {
        // Each cycle of n+1 slots runs the n+1 most frequent remaining tasks
        sort.Sort(sort.Reverse(sort.IntSlice(freqs)))
        take := min(n+1, len(freqs))
        next := []int{}
        for i, f := range freqs {
            if i < take {
                f--
            }
            if f > 0 {
                next = append(next, f)
            }
        }
        // A full cycle (with idles) unless this was the last one
        if len(next) == 0 {
            time += take
        } else {
            time += n + 1
        }
        freqs = next
    }
    return time
}

