class Solution {
    public int leastInterval(char[] tasks, int n) {
        int[] count = new int[26];
        for (char t : tasks) count[t - 'A']++;
        int maxFreq = 0, maxCount = 0;
        for (int c : count) {
            if (c > maxFreq) { maxFreq = c; maxCount = 1; }
            else if (c == maxFreq) maxCount++;
        }
        // (maxFreq-1) full frames of n+1 slots, plus a final row of the most frequent tasks
        int frames = (maxFreq - 1) * (n + 1) + maxCount;
        return Math.max(frames, tasks.length);
    }
}

